      var base=Math.atan2(nb[1]-a[1],nb[0]-a[0]);
      var ang=base+(Math.random()<.5?-1:1)*hbaTlR(.3,.7);
      if(Math.sin(ang)<.18)ang=base+(ang>base?1:-1)*hbaTlR(.3,.55);
