      var ang=hbaAlR(-2.6,-0.5),v=hbaAlR(30,64),dx=Math.cos(ang)*v*hbaAlR(.8,1.4),dy=Math.sin(ang)*v+hbaAlR(40,70);
      if(capY!=null&&y+dy>capY)dy=capY-y;
