        b.style.boxShadow=ghost?'0 0 8px rgba(52,211,153,.4)':'0 0 12px rgba(52,211,153,.95), 0 0 26px rgba(52,211,153,.5)';
        var op=ghost?(.34-ghost*.1):1;
