            if(prh>0.45){for(var gg=1;gg<=3;gg++){var pe=Math.max(0,e-gg*0.10);var gy2=above+(p.y-above)*pe;drawHammer(p.x,gy2,(0.9+0.35*pe)*sz,-0.22+0.22*pe,0.16*(1-gg*0.25));}}
