          if(m.prog>=1){if(!m.hit){m.hit=true;flashes.push({x:mx,y:my,r:0,vr:(m.big?34:18)*sz,life:0,max:m.big?420:280});if(m.big&&!dealt){dealt=true;if(deal){try{deal();}catch(e){}}}}meteors.splice(i9,1);continue;}
