        for(var ci=0;ci<4;ci++){var cc=corners[ci];var cx2=tgtX+cc[0]*box,cy2=tgtY+cc[1]*box*0.6;
          ctx.beginPath();ctx.moveTo(cx2,cy2+cc[1]*cn);ctx.lineTo(cx2,cy2);ctx.lineTo(cx2-cc[0]*cn,cy2);ctx.stroke();}
