          ctx.fillStyle=fg;ctx.beginPath();ctx.moveTo(0,-10*sz*flick);ctx.lineTo(48*sz*flick,0);ctx.lineTo(0,10*sz*flick);ctx.closePath();ctx.fill();ctx.restore();
