        var gr=ctx.createRadialGradient(cx,cy,0,cx,cy,R);gr.addColorStop(0,g('255,255,255,'+(pr*0.5)));gr.addColorStop(.4,g(C_BLUE+','+(pr*0.5)));gr.addColorStop(1,g(C_BLUE+',0'));
