      ctx.beginPath(); ctx.moveTo(-8.6*sz,-3.2*sz); ctx.lineTo(-13*sz,-6.6*sz); ctx.lineTo(-6*sz,-3.2*sz); ctx.closePath(); ctx.fill(); ctx.stroke();
      ctx.beginPath(); ctx.moveTo(-8.6*sz,3.2*sz); ctx.lineTo(-13*sz,6.6*sz); ctx.lineTo(-6*sz,3.2*sz); ctx.closePath(); ctx.fill(); ctx.stroke();
