      ctx.fillStyle=kg; ctx.beginPath(); ctx.moveTo(-3*sz,12*sz); ctx.lineTo(-2*sz,-34*sz); ctx.lineTo(1.4*sz,-40*sz); ctx.lineTo(3*sz,12*sz); ctx.closePath(); ctx.fill();
