    ctx.fillStyle=eg; ctx.strokeStyle='#1a1e26'; ctx.lineWidth=0.8;
    ctx.beginPath(); ctx.moveTo(-3.4,0); ctx.lineTo(-2.4,3.4); ctx.lineTo(2.4,3.4); ctx.lineTo(3.4,0); ctx.closePath(); ctx.fill(); ctx.stroke();
    /* 控制段(银)+红激活钮 */
