    ctx.fillStyle=cg; ctx.fillRect(-2.8,3.4,5.6,5.2); ctx.strokeRect(-2.8,3.4,5.6,5.2);
    ctx.fillStyle='#e83030'; ctx.beginPath(); ctx.arc(2.1,6,1.05,0,6.283); ctx.fill();
